### 2. Add BOQ + Quote API functions to src/lib/api.ts
Append these after existing functions:
```typescript
export async function listBoqs(projectId: string, params?: { page?: number; page_size?: number }): Promise<BOQListResponse> {
  const { page = 1, page_size = 20 } = params ?? {};
  const { data } = await axios.get<BOQListResponse>(`/api/projects/${projectId}/boqs`, { params: { page, page_size } });
  return data;
}

export async function getBoq(id: string): Promise<BOQ> {
  const { data } = await axios.get<BOQ>(`/api/boqs/${id}`);
  return data;
}

export async function getBoqItems(id: string, params?: { page?: number; page_size?: number }) {
  const { page = 1, page_size = 50 } = params ?? {};
  const { data } = await axios.get<{ items: BOQItem[]; total: number; page: number; page_size: number }>(`/api/boqs/${id}/items`, { params: { page, page_size } });
  return data;
}

export async function uploadBoq(projectId: string, file: File, notes?: string): Promise<BOQ> {
  const form = new FormData();
  form.append("file", file);
  if (notes) form.append("notes", notes);
  const { data } = await axios.post<BOQ>(`/api/projects/${projectId}/boqs`, form);
  return data;
}

export async function deleteBoq(id: string): Promise<void> {
  await axios.delete(`/api/boqs/${id}`);
}

export async function listQuotes(projectId: string, params?: { page?: number; page_size?: number }): Promise<QuoteListResponse> {
  const { page = 1, page_size = 20 } = params ?? {};
  const { data } = await axios.get<QuoteListResponse>(`/api/projects/${projectId}/quotes`, { params: { page, page_size } });
  return data;
}

export async function getQuote(id: string): Promise<Quote> {
  const { data } = await axios.get<Quote>(`/api/quotes/${id}`);
  return data;
}

export async function createQuote(projectId: string, payload: { boq_id: string; markup_percent?: number; tax_percent?: number; terms?: string; validity_days?: number }): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/projects/${projectId}/quotes`, payload);
  return data;
}

export async function updateQuote(id: string, payload: Partial<Quote>): Promise<Quote> {
  const { data } = await axios.patch<Quote>(`/api/quotes/${id}`, payload);
  return data;
}

export async function deleteQuote(id: string): Promise<void> {
  await axios.delete(`/api/quotes/${id}`);
}

export async function submitQuote(id: string): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/quotes/${id}/submit`);
  return data;
}

export async function approveQuote(id: string): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/quotes/${id}/approve`);
  return data;
}

export async function sendQuote(id: string): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/quotes/${id}/send`);
  return data;
}

export async function respondQuote(id: string, payload: { response: "accepted" | "rejected"; notes?: string }): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/quotes/${id}/respond`, payload);
  return data;
}

export async function cloneQuote(id: string): Promise<Quote> {
  const { data } = await axios.post<Quote>(`/api/quotes/${id}/clone`);
  return data;
}

export function downloadQuotePdf(id: string): void {
  const token = localStorage.getItem("access_token");
  window.open(`/api/quotes/${id}/pdf`, "_blank");
}
```

### 3. Create src/hooks/useBoqs.ts
```typescript
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { listBoqs, getBoq, getBoqItems, uploadBoq, deleteBoq } from "@/lib/api";

export function useBoqs(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["boqs", projectId, page, pageSize],
    queryFn: () => listBoqs(projectId, { page, page_size: pageSize }),
  });
}

export function useBoq(boqId: string) {
  return useQuery({
    queryKey: ["boq", boqId],
    queryFn: () => getBoq(boqId),
    enabled: !!boqId,
  });
}

export function useBoqItems(boqId: string, page = 1, pageSize = 50) {
  return useQuery({
    queryKey: ["boq-items", boqId, page, pageSize],
    queryFn: () => getBoqItems(boqId, { page, page_size: pageSize }),
    enabled: !!boqId,
  });
}

export function useUploadBoq() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, file, notes }: { projectId: string; file: File; notes?: string }) =>
      uploadBoq(projectId, file, notes),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}

export function useDeleteBoq() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ boqId, projectId }: { boqId: string; projectId: string }) =>
      deleteBoq(boqId),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}
```

### 4. Create src/hooks/useQuotes.ts
```typescript
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { listQuotes, getQuote, createQuote, updateQuote, deleteQuote, submitQuote, approveQuote, sendQuote, respondQuote, cloneQuote } from "@/lib/api";
import { QuoteStatus } from "@/types/api";

export function useQuotes(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["quotes", projectId, page, pageSize],
    queryFn: () => listQuotes(projectId, { page, page_size: pageSize }),
  });
}

export function useQuote(quoteId: string) {
  return useQuery({
    queryKey: ["quote", quoteId],
    queryFn: () => getQuote(quoteId),
    enabled: !!quoteId,
  });
}

export function useCreateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, ...payload }: { projectId: string } & Parameters<typeof createQuote>[1]) =>
      createQuote(projectId, payload),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useUpdateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ quoteId, projectId, ...payload }: { quoteId: string; projectId: string } & Parameters<typeof updateQuote>[1]) =>
      updateQuote(quoteId, payload),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quote", variables.quoteId] });
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useDeleteQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      deleteQuote(quoteId),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useSubmitQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      submitQuote(quoteId),
    onSuccess: () => {},
  });
}

export function useApproveQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      approveQuote(quoteId),
    onSuccess: () => {},
  });
}

export function useSendQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      sendQuote(quoteId),
    onSuccess: () => {},
  });
}

export function useRespondQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId, response, notes }: { quoteId: string; projectId: string; response: "accepted" | "rejected"; notes?: string }) =>
      respondQuote(quoteId, { response, notes }),
    onSuccess: () => {},
  });
}

export function useCloneQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      cloneQuote(quoteId),
    onSuccess: () => {},
  });
}
