### 6. Create BOQ components

#### src/components/boqs/BOQUpload.tsx
```tsx
import { useState } from "react";
import { useUploadBoq } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface BOQUploadProps {
  projectId: string;
}

export function BOQUpload({ projectId }: BOQUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [notes, setNotes] = useState("");
  const uploadMutation = useUploadBoq();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    await uploadMutation.mutateAsync({ projectId, file, notes });
    setFile(null);
    setNotes("");
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Upload BOQ</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="boq-file">BOQ File (.xlsx, .json)</Label>
            <Input
              id="boq-file"
              type="file"
              accept=".xlsx,.json"
              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="boq-notes">Notes (optional)</Label>
            <Textarea
              id="boq-notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Add notes about this BOQ version..."
            />
          </div>
          <Button type="submit" disabled={!file || uploadMutation.isPending}>
            {uploadMutation.isPending ? "Uploading..." : "Upload BOQ"}
          </Button>
          {uploadMutation.isError && (
            <p className="text-sm text-red-500">Upload failed. Please try again.</p>
          )}
        </form>
      </CardContent>
    </Card>
  );
}
```

#### src/components/boqs/BOQVersionList.tsx
```tsx
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useBoqs } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight, Trash2 } from "lucide-react";

interface BOQVersionListProps {
  projectId: string;
  onViewVersion: (boqId: string) => void;
}

export function BOQVersionList({ projectId, onViewVersion }: BOQVersionListProps) {
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const { data, isLoading } = useBoqs(projectId, page, pageSize);
  const deleteMutation = useMutation(useBoqs().mutate ?? (() => {}));
  const queryClient = useQueryClient();

  const boqs = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  return (
    <Card>
      <CardHeader>
        <CardTitle>BOQ Versions</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Version</TableHead>
                <TableHead>File Name</TableHead>
                <TableHead>Items</TableHead>
                <TableHead>Parsed By</TableHead>
                <TableHead>Date</TableHead>
                <TableHead>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center">Loading...</TableCell>
                </TableRow>
              ) : boqs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center">No BOQ versions uploaded</TableCell>
                </TableRow>
              ) : (
                boqs.map((boq) => (
                  <TableRow key={boq.id}>
                    <TableCell>v{boq.version_number}</TableCell>
                    <TableCell>{boq.file_name}</TableCell>
                    <TableCell>{boq.item_count ?? "—"}</TableCell>
                    <TableCell>{boq.parsed_by_name ?? "—"}</TableCell>
                    <TableCell>{new Date(boq.parsed_at).toLocaleDateString()}</TableCell>
                    <TableCell>
                      <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={() => onViewVersion(boq.id)}>
                          View
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={async () => {
                            if (confirm("Delete this BOQ version?")) {
                              const { deleteBoq } = await import("@/lib/api");
                              await deleteBoq(boq.id);
                              queryClient.invalidateQueries({ queryKey: ["boqs", projectId] });
                            }
                          }}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
        <div className="flex items-center justify-between mt-4">
          <span className="text-sm text-muted-foreground">{total} version(s)</span>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <span className="text-sm">Page {page} of {totalPages}</span>
            <Button variant="outline" size="sm" onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page >= totalPages}>
              <ArrowRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
```

