import { useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useSubmitQuote, useApproveQuote, useSendQuote, useRespondQuote, useCloneQuote } from "@/hooks/useQuotes";
import { Quote } from "@/types/api";
import { downloadQuotePdf } from "@/lib/api";

interface QuoteActionsProps {
  quote: Quote;
  projectId: string;
  onQuoteUpdate?: () => void;
}

export function QuoteActions({ quote, projectId, onQuoteUpdate }: QuoteActionsProps) {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";

  const submitMutation = useSubmitQuote();
  const approveMutation = useApproveQuote();
  const sendMutation = useSendQuote();
  const respondMutation = useRespondQuote();
  const cloneMutation = useCloneQuote();

  const handleSubmit = async () => {
    await submitMutation.mutateAsync({ quoteId: quote.id, projectId });
    onQuoteUpdate?.();
  };

  const handleApprove = async () => {
    await approveMutation.mutateAsync({ quoteId: quote.id, projectId });
    onQuoteUpdate?.();
  };

  const handleSend = async () => {
    await sendMutation.mutateAsync({ quoteId: quote.id, projectId });
    onQuoteUpdate?.();
  };

  const handleRespond = async (response: "accepted" | "rejected") => {
    await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response });
    onQuoteUpdate?.();
  };

  const handleClone = async () => {
    await cloneMutation.mutateAsync({ quoteId: quote.id, projectId });
    onQuoteUpdate?.();
  };

  return (
    <div className="flex flex-wrap gap-2">
      <Button variant="outline" size="sm" onClick={() => downloadQuotePdf(quote.id)}>
        Download PDF
      </Button>
      {quote.status === "draft" && (
        <Button size="sm" onClick={handleSubmit} disabled={submitMutation.isPending}>
          Submit for Approval
        </Button>
      )}
      {quote.status === "pending_approval" && isAdmin && (
        <>
          <Button size="sm" onClick={handleApprove} disabled={approveMutation.isPending}>
            Approve
          </Button>
          <Button size="sm" variant="outline" onClick={() => handleRespond("rejected")} disabled={respondMutation.isPending}>
            Reject to Draft
          </Button>
        </>
      )}
      {quote.status === "approved" && (
        <Button size="sm" onClick={handleSend} disabled={sendMutation.isPending}>
          Send to Client
        </Button>
      )}
      {quote.status === "sent" && (
        <>
          <Button size="sm" onClick={() => handleRespond("accepted")} disabled={respondMutation.isPending}>
            Accept
          </Button>
          <Button size="sm" variant="destructive" onClick={() => handleRespond("rejected")} disabled={respondMutation.isPending}>
            Reject
          </Button>
        </>
      )}
      {quote.status === "rejected" && (
        <Button size="sm" onClick={handleClone} disabled={cloneMutation.isPending}>
          Clone to Draft
        </Button>
      )}
    </div>
  );
}
